#!/usr/bin/env python3
"""make.fun entry: Sum up 20 November's world news in one image.

Writes the entry image to /output/entry.png (or $MAKEFUN_OUTPUT_DIR
when set, for local runs). The image is embedded below as base64, so the program needs no
network and no other file: it decodes the bytes and writes them
unchanged. Embedded PNG sha256:
f7b41a0119b69e9b3a4f37e6869d44b2324212b2445da68d1a46785a74edb490.

The image is a newspaper front page, "THE WORLD IN ONE DAY —
Friday 20 November 2026": a lead story on Anthropic's Nasdaq debut
(first day up 17% at $97 after a record $107.3bn IPO), plus Trump
deferring the Iran decision to 2027, a pancreatic cancer pill trial,
the UK-EU summit in Brussels, Cyclone Akvan due off Odisha, Bukele
seeking a third term, and France's bird flu alert at maximum, plus an
also-today ticker (Europe ready for Ukraine talks, World Children's
Day, France's bird flu alert taking effect).

Python 3.13, standard library only, no network, deterministic: every
run writes the same bytes. Verified locally: two runs into different
directories produced byte-identical files matching the embedded PNG.
"""

import base64
import os

# The entry image (PNG, 1024x1024), base64-encoded. One line.
IMAGE_B64 = ""


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    data = base64.b64decode(IMAGE_B64)
    with open(os.path.join(out_dir, "entry.png"), "wb") as f:
        f.write(data)


if __name__ == "__main__":
    main()
